/* ---- film 112 helpers ---- */
function map112(px, py, pw, ph, x0, x1, y0, y1) { return [x => px + (x - x0) / (x1 - x0) * pw, y => py - (y - y0) / (y1 - y0) * ph]; }
function poly112(xs, ys, X, Y, col, a, lw = 3, prog = 1, ymin = -1e9, ymax = 1e9) {
  if (a <= 0) return;
  const n = Math.max(2, Math.floor(xs.length * clamp(prog)));
  ctx.save(); ctx.globalAlpha = a; ctx.strokeStyle = col; ctx.lineWidth = lw; ctx.beginPath();
  let on = false;
  for (let i = 0; i < n; i++) { const y = ys[i]; if (y < ymin || y > ymax || !isFinite(y)) { on = false; continue; } const px = X(xs[i]), py = Y(y); if (!on) { ctx.moveTo(px, py); on = true; } else ctx.lineTo(px, py); }
  ctx.stroke(); ctx.restore();
}
function dpoly112(pts, col, a, lw = 2) { if (a <= 0) return; ctx.save(); ctx.setLineDash([9, 8]); strokePoly(pts, col, a, lw, false); ctx.restore(); }
function cell112(x, y, w, h, s, col, a, size = 18, fillA = 0.3) { if (a <= 0) return; fillBox(x, y, w, h, col, a * fillA); rect63(x, y, w, h, col, a, 1.6); lbl(s, x + w / 2, y + h / 2 + size * 0.35, C.white, a, size); }
/* the steering body B = conv{±c(k)} : computed hull, rotating */
function body112(cx, cy, s, ang, a, o = {}) {
  if (a <= 0) return;
  const P = HULL112.pts, n = HULL112.ncurve, tilt = o.tilt == null ? 0.38 : o.tilt;
  const pr = q => { let p = [q[0] * s, -q[2] * s, q[1] * s]; p = rotY(p, ang); p = rotX(p, tilt); return proj(p, cx, cy, 1400, 1400); };
  const Q2 = P.map(pr);
  HULL112.edges.forEach(([i, j]) => line(Q2[i][0], Q2[i][1], Q2[j][0], Q2[j][1], C.cyan, a * 0.16, 1));
  const f1 = Q2.slice(0, n).map(p => [p[0], p[1]]), f2 = Q2.slice(n).map(p => [p[0], p[1]]);
  fillPoly(f1, C.gold, a * (o.faceA == null ? 0.16 : o.faceA)); fillPoly(f2, C.mag, a * 0.12);
  strokePoly(f1, C.gold, a, 3, false); strokePoly(f2, C.mag, a, 3, false);
  dashed(f1[0][0], f1[0][1], f1[n - 1][0], f1[n - 1][1], C.gold, a * 0.6, 1.5); dashed(f2[0][0], f2[0][1], f2[n - 1][0], f2[n - 1][1], C.mag, a * 0.6, 1.5);
  if (o.ell) {
    const V = HULL112.evecs, L = HULL112.evals;
    [[0, 1], [0, 2], [1, 2]].forEach(([i, j]) => {
      const pts = []; for (let k = 0; k <= 72; k++) { const th = TAU * k / 72, ci = Math.sqrt(L[i]) * Math.cos(th), cj = Math.sqrt(L[j]) * Math.sin(th); const q = [0, 1, 2].map(r => V[r][i] * ci + V[r][j] * cj); const p = pr(q); pts.push([p[0], p[1]]); }
      strokePoly(pts, C.green, a * o.ell, 2.2, true);
    });
  }
  if (o.atoms) {
    const po = pr([0, 0, 0]);
    HULL112.atoms.forEach((q, i) => { const p = pr(q); line(po[0], po[1], p[0], p[1], C.white, a * o.atoms * 0.35, 1.2); dot(p[0], p[1], 11, GAUGE112.beta[i] > 0 ? 'g' : 'm', a * o.atoms); });
    const pw_ = pr(HULL112.wdir.map(x => x * 1.0)); arrow(po[0], po[1], pw_[0], pw_[1], C.green, a * o.atoms, 3);
  }
  if (o.lab) {
    const pa = Q2[Math.floor(n / 2)], pb = Q2[n + Math.floor(n / 2)];
    lbl('+c(k)', pa[0] + 16, pa[1] - 10, C.gold, a, 17, 'left'); lbl('−c(k)', pb[0] - 16, pb[1] + 24, C.mag, a, 17, 'right');
  }
}
const LG112 = Math.log10;
function axes112(x0, y0, w, h, a, xl, yl) { line(x0, y0, x0 + w, y0, C.dim, a, 1.5); line(x0, y0, x0, y0 - h, C.dim, a, 1.5); if (xl) txt(xl, x0 + w / 2, y0 + 58, { size: 17, fam: F.mono, w: 700, align: 'center', c: C.dim, a }); if (yl) txt(yl, x0, y0 - h - 16, { size: 17, fam: F.mono, w: 700, align: 'left', c: C.dim, a }); }

